/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('notifications')` (or `ctx.tryUse` for an optional dependency). */
export interface NotificationsPublicApi {
  /** Send a topic to recipients now (for cases not covered by the event routing rules, e.g. mentions, test notices, guest order links). Essential topics ignore promotional consent; promotional topics check it. Used by: customers, support, messaging, sellers, finance, returns, workqueues, access, reports, audit, fulfillment-service. */
  notify(input: NotifyInput): Promise<{ noticeIds: string[], deliveryIds: string[] }>;
  /** Send later (deadline reminders). Requires a dedupeKey so it can be cancelled. Used by: shipping, orders, returns, sellers, support, access. */
  schedule(input: NotifyInput, sendAt: string): Promise<string>;
  /** Cancel scheduled notices (e.g. order dispatched before the reminder) Used by: shipping, orders, returns, sellers, support, access. */
  cancelScheduled(dedupeKey: string): Promise<number>;
  /** Mark action-required notices as done for every recipient (the queue item was handled), so inboxes stop showing them as needing action Used by: workqueues, support, access, finance, sellers, shipping, returns. */
  resolve(dedupeKey: string, note?: string): Promise<number>;
  /** Consent, suppression and account status check before any promotional send Used by: promotions, advertising, wishlist, reviews. */
  canSendPromotional(recipient: Recipient, channel: 'email' | 'sms' | 'push'): Promise<boolean>;
  /** Tokens in promotional footers are signed here; customers' public unsubscribe endpoint verifies them Used by: customers. */
  verifyUnsubscribeToken(token: string): Promise<{ audience: 'customer' | 'seller', accountId: string | null, email: string, channel: 'email' | 'sms' | 'push', topicGroup: string } | null>;
  /** Badge count for navigation responses of other modules Used by: customers, sellers, graphql. */
  unreadCount(principal: identity.Principal): Promise<number>;
  /** The caller's own inbox, newest first: customer (store), seller member within the current seller (Seller Center), staff member including notices received as backup (Admin Center). Same rules as GET /inbox in each area. Used by: graphql. */
  listInbox(principal: identity.Principal, filter: { group?: string, unreadOnly?: boolean, actionRequired?: boolean, category?: 'essential' | 'optional' | 'promotional', view?: 'all' | 'needs_my_action' | 'mentions' }, page: common.PageInput): Promise<common.Page<Notice>>;
  /** Unread per group, open action notices (max 10, by deadline) and, for staff, needs-my-action, mentions and routing today. Same data as GET /inbox/summary in each area. Used by: graphql. */
  inboxSummary(principal: identity.Principal): Promise<InboxSummary & Partial<StaffInboxSummary>>;
}

